def no_of_subsequences(arr, k):
    n = len(arr)
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(1, k + 1):
            if arr[i - 1] <= j:
                dp[i][j] = dp[i - 1][j] + dp[i - 1][j // arr[i - 1]]
            else:
                dp[i][j] = dp[i - 1][j]

    return dp[n][k]
```

